function run_em_design_from_json(input_json_path, output_json_path)
%RUN_EM_DESIGN_FROM_JSON Fixed LiveLink entrypoint for em-design-mcp.
%   The input JSON is generated by the Python backend. It contains only
%   high-level candidate values plus profile-provided bindings and tags.

result = struct();
result.status = 'error';
result.warnings = {};
result.errors = {};
result.failure_category = 'backend_execution_error';

try
    ensure_parent_dir(output_json_path);
    request = jsondecode(fileread(input_json_path));

    import com.comsol.model.*
    import com.comsol.model.util.*

    runtime = get_optional(request, 'runtime', struct());
    comsol_mli_path = get_optional(runtime, 'comsol_mli_path', '');
    if strlength(string(comsol_mli_path)) > 0
        addpath(char(comsol_mli_path));
    end

    mphstart(double(get_optional(runtime, 'comsol_server_port', 2036)));
    model_tag = ['em_' strrep(char(java.util.UUID.randomUUID), '-', '')];
    model = mphload(char(request.model.mph_path), model_tag);
    cleanup = onCleanup(@() release_owned_model(model_tag)); %#ok<NASGU>

    bindings = get_optional(request, 'model_bindings', struct());
    candidate = request.candidate;

    mode = char(get_optional(request, 'mode', 'evaluate'));
    if ~any(strcmp(mode, {'evaluate', 'inspect'}))
        error('em:unsupported_mode', 'Unsupported fixed entrypoint mode: %s', mode);
    end
    if strcmp(mode, 'evaluate') || logical(get_optional(request, 'apply_candidate', false))
        apply_parameter_bindings(model, candidate, bindings);
        apply_shape_switch(model, candidate, bindings);
        apply_material_switch(model, candidate, bindings);
        apply_feature_switches(model, candidate, bindings);
        apply_sweep_bindings(model, request, bindings);
        % Selections must describe the candidate geometry, not cached entities.
        components = cellstr(string(model.component.tags));
        for ci = 1:numel(components)
            geometries = cellstr(string(model.component(components{ci}).geom.tags));
            for gi = 1:numel(geometries)
                model.component(components{ci}).geom(geometries{gi}).run;
            end
        end
    end
    topics = get_optional(request, 'topics', {'studies', 'outputs'});
    measurements = get_optional(request, 'measurements', []);
    if strcmp(mode, 'inspect')
        result.model_facts = em_model_facts(model, topics);
        result.measurements = em_named_measurements(model, measurements);
        result.status = 'ok'; result.failure_category = [];
        write_json(output_json_path, result);
        return
    end

    tags = get_optional(bindings, 'tags', struct());
    table_tag = get_optional(tags, 'table', '');
    if strlength(string(table_tag)) > 0
        model.result.table(char(table_tag)).clearTableData;
    end

    study_tags = get_optional(tags, 'studies', {});
    if isempty(study_tags)
        study_tags = {char(require_binding(tags, 'study'))};
    end
    study_tags = cellstr(string(study_tags));
    recomputed_solutions = {};
    for mi = 1:numel(measurements)
        if iscell(measurements); measurement = measurements{mi}; else; measurement = measurements(mi); end
        if ~any(strcmp(char(measurement.study), study_tags))
            error('em:stale_solution', 'Measurement %s references study %s which this run did not execute.', char(measurement.id), char(measurement.study));
        end
        solution_tag = char(measurement.solution);
        if ~any(strcmp(solution_tag, recomputed_solutions))
            % This is an isolated loaded copy. Clearing only declared output
            % solutions proves that a nonempty result was computed by this run,
            % even when several solver sequences belong to the same study.
            % Continuation from these saved solutions is intentionally unsupported.
            model.sol(solution_tag).clearSolutionData;
            if ~logical(model.sol(solution_tag).isEmpty())
                error('em:stale_solution', 'Could not clear measurement solution %s.', solution_tag);
            end
            recomputed_solutions{end+1} = solution_tag; %#ok<AGROW>
        end
    end
    for si = 1:numel(study_tags)
        model.study(study_tags{si}).run;
    end
    result.model_facts = em_model_facts(model, topics);
    result.measurements = em_named_measurements(model, measurements);

    eval_tag = get_optional(tags, 'eval_feature', '');
    if strlength(string(eval_tag)) > 0
        result_dataset = get_optional(tags, 'result_dataset', '');
        if strlength(string(result_dataset)) > 0
            model.result.numerical(char(eval_tag)).set('data', char(result_dataset));
        end
        eval_outerinput = get_optional(tags, 'eval_outerinput', '');
        if strlength(string(eval_outerinput)) > 0
            model.result.numerical(char(eval_tag)).set('outerinput', char(eval_outerinput));
        end
        model.result.numerical(char(eval_tag)).setResult;
    end

    output_dir = char(request.model.output_dir);
    if ~exist(output_dir, 'dir')
        mkdir(output_dir);
    end
    table_path = fullfile(output_dir, [char(request.run_id) '.txt']);

    export_tag = get_optional(tags, 'export', '');
    if strlength(string(export_tag)) > 0
        model.result.export(char(export_tag)).set('filename', table_path);
        model.result.export(char(export_tag)).run;
    end

    outputs = get_optional(bindings, 'outputs', struct());
    solved_model_path = '';
    if logical(get_optional(outputs, 'save_solved_model', false))
        solved_model_path = fullfile(output_dir, [char(request.run_id) '.mph']);
        mphsave(model, solved_model_path);
    end

    % Python parsers are the source of truth for exported table columns.
    % MATLAB only reports artifacts so profile-declared parser settings are
    % applied consistently by the backend.
    simulation_output = struct();
    simulation_output.summary_metrics = struct();
    simulation_output.model_facts = result.model_facts;
    simulation_output.measurements = result.measurements;
    simulation_output.recomputed_solutions = recomputed_solutions;
    simulation_output.artifacts = struct('table_path', table_path, 'input_json_path', char(input_json_path));
    if strlength(string(solved_model_path)) > 0
        simulation_output.artifacts.solved_model_path = solved_model_path;
    end

    result.status = 'ok';
    result.failure_category = [];
    result.simulation_output = simulation_output;
    result.artifacts = simulation_output.artifacts;
    result.errors = {};
    write_json(output_json_path, result);
catch ME
    result.status = 'error';
    result.failure_category = classify_error(ME);
    result.errors = {getReport(ME, 'extended', 'hyperlinks', 'off')};
    write_json(output_json_path, result);
end
end

function release_owned_model(tag)
try; com.comsol.model.util.ModelUtil.remove(tag); catch; end
try; com.comsol.model.util.ModelUtil.disconnect; catch; end
end

function apply_parameter_bindings(model, candidate, bindings)
parameters = get_optional(bindings, 'parameters', struct());
if ~isstruct(parameters)
    return
end
names = fieldnames(parameters);
for idx = 1:numel(names)
    candidate_field = names{idx};
    if ~isfield(candidate, candidate_field)
        continue
    end
    binding = parameters.(candidate_field);
    parameter_name = resolve_parameter_name(binding);
    unit = resolve_unit(binding);
    value = candidate.(candidate_field);
    if ~(isnumeric(value) || islogical(value))
        error('Candidate field %s is bound as a COMSOL parameter but is not numeric.', candidate_field);
    end
    model.param.set(char(parameter_name), format_comsol_value(value, unit));
end
end

function apply_sweep_bindings(model, request, bindings)
sweeps = get_optional(bindings, 'sweeps', []);
if isempty(sweeps)
    return
end
for idx = 1:numel(sweeps)
    if iscell(sweeps)
        sweep = sweeps{idx};
    else
        sweep = sweeps(idx);
    end
    study_tag = require_binding(sweep, 'study_tag');
    feature_tag = require_binding(sweep, 'feature_tag');
    parameter_name = get_optional(sweep, 'parameter', '');
    unit = get_optional(sweep, 'unit', '');
    kind = char(get_optional(sweep, 'kind', ''));

    if strlength(string(parameter_name)) > 0
        model.study(char(study_tag)).feature(char(feature_tag)).set('pname', {char(parameter_name)});
    end
    if strlength(string(unit)) > 0
        model.study(char(study_tag)).feature(char(feature_tag)).set('punit', {char(unit)});
    end

    if strcmp(kind, 'range')
        start_field = require_binding(sweep, 'start_field');
        stop_field = require_binding(sweep, 'stop_field');
        start_value = request.candidate.(char(start_field));
        stop_value = request.candidate.(char(stop_field));
        step_value = get_optional(sweep, 'step', 1);
        expression = sprintf('range(%.15g,%.15g,%.15g)', double(start_value), double(step_value), double(stop_value));
        model.study(char(study_tag)).feature(char(feature_tag)).set('plistarr', {expression});
    elseif strcmp(kind, 'values')
        values = resolve_sweep_values(request, sweep);
        expression = join_sweep_values(values, unit);
        model.study(char(study_tag)).feature(char(feature_tag)).set('plistarr', {expression});
    else
        error('Unsupported sweep binding kind: %s', kind);
    end
end
end

function apply_shape_switch(model, candidate, bindings)
shape_switch = get_optional(bindings, 'shape_switch', struct());
if ~isstruct(shape_switch) || ~isfield(shape_switch, 'candidate_field')
    return
end
candidate_field = char(shape_switch.candidate_field);
if ~isfield(candidate, candidate_field)
    return
end
shape_value = char(candidate.(candidate_field));
options = require_binding(shape_switch, 'options');
option_field = matlab.lang.makeValidName(shape_value);
if ~isfield(options, option_field)
    error('No profile shape_switch option is declared for candidate value: %s', shape_value);
end
option = options.(option_field);
active_features = require_binding(option, 'active_features');
component_tag = require_binding(shape_switch, 'component_tag');
geometry_tag = require_binding(shape_switch, 'geometry_tag');
feature_tags = fieldnames(active_features);
for idx = 1:numel(feature_tags)
    feature_tag = feature_tags{idx};
    model.component(char(component_tag)).geom(char(geometry_tag)).feature(feature_tag).active(logical(active_features.(feature_tag)));
end
if logical(get_optional(shape_switch, 'rebuild', false))
    model.component(char(component_tag)).geom(char(geometry_tag)).run;
    mesh_tag = get_optional(shape_switch, 'mesh_tag', '');
    if strlength(string(mesh_tag)) > 0
        model.component(char(component_tag)).mesh(char(mesh_tag)).run;
    end
end
end

function apply_material_switch(model, candidate, bindings)
material_switch = get_optional(bindings, 'material_switch', struct());
if ~isstruct(material_switch) || ~isfield(material_switch, 'candidate_field')
    return
end
candidate_field = char(material_switch.candidate_field);
if ~isfield(candidate, candidate_field)
    return
end
material_value = char(candidate.(candidate_field));
options = require_binding(material_switch, 'options');
option_field = matlab.lang.makeValidName(material_value);
if ~isfield(options, option_field)
    error('No profile material_switch option is declared for candidate value: %s', material_value);
end
option = options.(option_field);
active_materials = require_binding(option, 'active_materials');
component_tag = require_binding(material_switch, 'component_tag');
material_tags = fieldnames(active_materials);
for idx = 1:numel(material_tags)
    material_tag = material_tags{idx};
    model.component(char(component_tag)).material(material_tag).active(logical(active_materials.(material_tag)));
end
end

function apply_feature_switches(model, candidate, bindings)
feature_switches = get_optional(bindings, 'feature_switches', []);
if isempty(feature_switches)
    return
end
for switch_idx = 1:numel(feature_switches)
    if iscell(feature_switches)
        feature_switch = feature_switches{switch_idx};
    else
        feature_switch = feature_switches(switch_idx);
    end
    candidate_field = require_binding(feature_switch, 'candidate_field');
    candidate_field = char(candidate_field);
    if ~isfield(candidate, candidate_field)
        continue
    end
    selected_value = char(candidate.(candidate_field));
    options = require_binding(feature_switch, 'options');
    option_field = matlab.lang.makeValidName(selected_value);
    if ~isfield(options, option_field)
        error('No profile feature_switch option is declared for candidate value: %s', selected_value);
    end
    option = options.(option_field);
    features = require_binding(option, 'features');
    for feature_idx = 1:numel(features)
        if iscell(features)
            feature_binding = features{feature_idx};
        else
            feature_binding = features(feature_idx);
        end
        path = require_binding(feature_binding, 'path');
        active_state = logical(require_binding(feature_binding, 'active'));
        component_tag = require_binding(path, 'component');
        physics_tag = require_binding(path, 'physics');
        parent_feature_tag = require_binding(path, 'parent_feature');
        feature_tag = require_binding(path, 'feature');
        feature = model.component(char(component_tag)).physics(char(physics_tag)).feature(char(parent_feature_tag)).feature(char(feature_tag));
        feature.active(active_state);
    end
end
end

function parsed = parse_comsol_table(table_path, wavelengths_nm)
rows = [];
fid = fopen(table_path, 'r');
if fid < 0
    error('Unable to open COMSOL table export: %s', table_path);
end
cleanup = onCleanup(@() fclose(fid));
while true
    line = fgetl(fid);
    if ~ischar(line)
        break
    end
    line = strtrim(line);
    if isempty(line) || startsWith(line, '%') || startsWith(line, '#')
        continue
    end
    values = sscanf(line, '%f');
    if numel(values) >= 5
        rows(end + 1, 1:5) = values(1:5); %#ok<AGROW>
    elseif numel(values) >= 4 && numel(wavelengths_nm) == 1
        rows(end + 1, 1:5) = [values(1), wavelengths_nm(1), NaN, values(3), values(4)]; %#ok<AGROW>
    end
end
if isempty(rows)
    error('No numeric rows found in COMSOL table export: %s', table_path);
end

lam_values = unique(rows(:, 2));
data_by_lam = struct();
all_t = [];
for idx = 1:numel(lam_values)
    raw_lam = lam_values(idx);
    lam = snap_wavelength(raw_lam, wavelengths_nm);
    mask = rows(:, 2) == raw_lam;
    subset = rows(mask, :);
    [~, order] = sort(subset(:, 1));
    subset = subset(order, :);
    field_name = ['w_' regexprep(num2str(lam, '%.15g'), '[^A-Za-z0-9_]', '_')];
    data_by_lam.(field_name) = struct( ...
        'wavelength_nm', lam, ...
        'param_nm', subset(:, 1)', ...
        'T', subset(:, 4)', ...
        'phi_rad', subset(:, 5)' ...
    );
    all_t = [all_t; subset(:, 4)]; %#ok<AGROW>
end
summary_metrics = struct('mean_transmission', mean(all_t));
parsed = struct('data_by_lam', data_by_lam, 'summary_metrics', summary_metrics);
end

function parsed = parse_spectral_response_table(table_path)
rows = [];
fid = fopen(table_path, 'r');
if fid < 0
    error('Unable to open COMSOL table export: %s', table_path);
end
cleanup = onCleanup(@() fclose(fid));
while true
    line = fgetl(fid);
    if ~ischar(line)
        break
    end
    line = strtrim(line);
    if isempty(line) || startsWith(line, '%') || startsWith(line, '#')
        continue
    end
    values = sscanf(line, '%f');
    if numel(values) >= 5
        rows(end + 1, 1:5) = values(1:5); %#ok<AGROW>
    elseif numel(values) >= 2
        rows(end + 1, 1:5) = [values(1), NaN, values(2), NaN, NaN]; %#ok<AGROW>
    end
end
if isempty(rows)
    error('No numeric rows found in COMSOL spectral table export: %s', table_path);
end

wavelength_um = rows(:, 1)';
through = rows(:, 3)';
spectral_response = struct( ...
    'wavelength_um', wavelength_um, ...
    'through_transmission', through ...
);
if any(~isnan(rows(:, 2)))
    spectral_response.reflection = rows(:, 2)';
end
if any(~isnan(rows(:, 4)))
    spectral_response.total_reflection_transmission = rows(:, 4)';
end
if any(~isnan(rows(:, 5)))
    spectral_response.loss = rows(:, 5)';
end
[min_through, min_index] = min(through);
if numel(through) == 1
    off_resonance = through(1);
else
    off_resonance = mean([through(1), through(end)]);
end
summary_metrics = struct( ...
    'lambda_res_um', wavelength_um(min_index), ...
    'min_through_transmission', min_through, ...
    'off_resonance_transmission', off_resonance ...
);
parsed = struct('spectral_response', spectral_response, 'summary_metrics', summary_metrics);
end

function values = resolve_sweep_values(request, sweep)
from_candidate = false;
if isfield(sweep, 'values')
    raw_values = sweep.values;
else
    values_from = char(require_binding(sweep, 'values_from'));
    from_candidate = startsWith(values_from, 'candidate.');
    [found, raw_values] = resolve_dotted_path(request, values_from);
    if ~found
        error('Sweep values_from path could not be resolved: %s', values_from);
    end
end
values = coerce_sweep_values(raw_values);
if isempty(values)
    error('Values sweep resolved no values.');
end
% Candidate text would reach COMSOL as an expression (e.g. range(...)) whose
% size the Python cost gate cannot bound; accept only finite numbers.
if from_candidate && ~all(cellfun(@(v) isnumeric(v) && isscalar(v) && isfinite(v), values))
    error('em:sweep_values', 'Candidate-provided sweep values must be finite numbers.');
end
end

function [found, value] = resolve_dotted_path(root_struct, dotted_path)
parts = split(string(dotted_path), '.');
value = root_struct;
found = true;
for idx = 1:numel(parts)
    part = char(parts(idx));
    if isstruct(value)
        if numel(value) ~= 1
            found = false;
            value = [];
            return
        end
        valid_part = matlab.lang.makeValidName(part);
        if isfield(value, part)
            value = value.(part);
        elseif isfield(value, valid_part)
            value = value.(valid_part);
        else
            found = false;
            value = [];
            return
        end
    else
        found = false;
        value = [];
        return
    end
end
end

function values = coerce_sweep_values(raw_values)
values = {};
if isempty(raw_values)
    return
end
if isnumeric(raw_values) || islogical(raw_values)
    numeric_values = double(raw_values(:)');
    values = num2cell(numeric_values);
elseif iscell(raw_values)
    for idx = 1:numel(raw_values)
        values = [values, coerce_sweep_values(raw_values{idx})]; %#ok<AGROW>
    end
elseif isstring(raw_values)
    values = cellstr(raw_values(:))';
elseif ischar(raw_values)
    values = {strtrim(raw_values)};
else
    error('Unsupported values sweep data type: %s', class(raw_values));
end
end

function wavelengths = get_wavelengths(request)
wavelengths = [];
if isfield(request.problem_spec, 'independent_variables') && ...
        isfield(request.problem_spec.independent_variables, 'wavelength_nm')
    wavelengths = double(request.problem_spec.independent_variables.wavelength_nm);
end
end

function value = get_optional(source, name, default)
if isstruct(source) && isfield(source, name)
    value = source.(name);
else
    value = default;
end
end

function value = require_binding(source, name)
if ~(isstruct(source) && isfield(source, name))
    error('Required model profile binding is missing: %s', name);
end
value = source.(name);
end

function parameter_name = resolve_parameter_name(binding)
if isstruct(binding)
    parameter_name = require_binding(binding, 'comsol_parameter');
else
    parameter_name = binding;
end
end

function unit = resolve_unit(binding)
if isstruct(binding)
    unit = get_optional(binding, 'unit', '');
else
    unit = '';
end
end

function text = format_comsol_value(value, unit)
numeric_value = double(value);
if strlength(string(unit)) > 0
    text = sprintf('%.15g[%s]', numeric_value, char(unit));
else
    text = sprintf('%.15g', numeric_value);
end
end

function text = join_sweep_values(values, unit)
parts = cell(1, numel(values));
for idx = 1:numel(values)
    parts{idx} = format_sweep_value(values{idx}, unit);
end
text = strjoin(parts, ' ');
end

function text = format_sweep_value(value, unit)
if isnumeric(value) || islogical(value)
    if numel(value) ~= 1
        error('Sweep value arrays must be flattened before formatting.');
    end
    text = format_comsol_value(value, unit);
    return
end
if isstring(value)
    value = char(value);
end
if ischar(value)
    text_value = strtrim(value);
    numeric_value = str2double(text_value);
    if ~isnan(numeric_value) && strlength(string(unit)) > 0
        text = format_comsol_value(numeric_value, unit);
    else
        text = text_value;
    end
    return
end
error('Unsupported sweep value type: %s', class(value));
end

function lam = snap_wavelength(raw_lam, targets)
if isempty(targets)
    lam = raw_lam;
    return
end
[~, index] = min(abs(double(targets) - raw_lam));
lam = double(targets(index));
end

function category = classify_error(ME)
if startsWith(ME.identifier, 'em:measurement_')
    category = 'measurement_failed';
    return
elseif strcmp(ME.identifier, 'em:stale_solution')
    category = 'stale_solution';
    return
end
message = lower(getReport(ME, 'basic', 'hyperlinks', 'off'));
if contains(message, 'license checkout') || contains(message, 'license manager') || ...
        contains(message, 'license error') || contains(message, 'no licenses available')
    category = 'backend_license_error';
elseif contains(message, 'mphstart') || contains(message, 'failed to connect to server') || ...
        contains(message, 'connection refused') || contains(message, 'could not connect to comsol') || ...
        contains(message, 'comsol server')
    category = 'backend_connection_error';
elseif contains(message, 'timed out') || contains(message, 'timeout')
    category = 'backend_timeout';
elseif contains(message, 'parse') || contains(message, 'json') || contains(message, 'table')
    category = 'result_parse_error';
elseif contains(message, 'mesh')
    category = 'mesh_failure';
elseif contains(message, 'failed to find a solution') || contains(message, 'solver') || ...
        contains(message, 'nonconvergence') || contains(message, 'not converged') || ...
        contains(message, 'singular matrix')
    category = 'solver_nonconvergence';
else
    category = 'backend_execution_error';
end
end

function ensure_parent_dir(path)
parent = fileparts(char(path));
if ~isempty(parent) && ~exist(parent, 'dir')
    mkdir(parent);
end
end

function write_json(path, payload)
ensure_parent_dir(path);
fid = fopen(path, 'w');
if fid < 0
    error('Unable to write output JSON: %s', path);
end
cleanup = onCleanup(@() fclose(fid));
encoded = jsonencode(payload);
fwrite(fid, encoded, 'char');
end
